const heading=(ey,title,sub,action='')=>`<div class="pagehead"><div><div class="eyebrow">${ey}</div><h1>${title}</h1><p class="sub">${sub}</p></div>${action}</div>`;
function stats(){const rs=finalized(),sum=k=>rs.reduce((n,r)=>n+(Number(r[k])||0),0);return `<div class="stats"><div class="stat"><div class="stat-top">AGENCIAS DISPONIBLES ${icon('building')}</div><div class="value">${AGENCIES.length}</div><small>Directorio nacional · Bolivia</small></div><div class="stat"><div class="stat-top">REGISTROS FINALIZADOS ${icon('check')}</div><div class="value">${rs.length.toString().padStart(2,'0')}</div><small>${admin()?'Todos los perfiles':'Tu perfil'} · guardado local</small></div><div class="stat"><div class="stat-top">FALTANTE REGISTRADO ${icon('box')}</div><div class="value"><span class="unit">Bs</span>${money(sum('short'))}</div><small>Excluye pendientes de regularización</small></div><div class="stat"><div class="stat-top">BORRADORES ${icon('clock')}</div><div class="value">${visibleRecords().filter(r=>r.status==='draft').length.toString().padStart(2,'0')}</div><small>Continúa donde lo dejaste</small></div></div>`}
