function input(label,key,type='number',help='',opts={}){const val=opts.value??current[key]??'';return `<div class="field ${opts.full?'full':''}"><label for="${key}">${label}${opts.required?' *':''}</label>${opts.money?'<div class="moneywrap"><span>Bs</span>':''}<input id="${key}" data-field="${key}" type="${type}" value="${esc(val)}" ${type==='number'?`min="${opts.signed?'-999999999':'0'}" step="${opts.integer?'1':'0.01'}" inputmode="${opts.integer?'numeric':'decimal'}"`:''} ${opts.readonly?'readonly':''} ${opts.required?'required':''}>${opts.money?'</div>':''}${help?`<small>${help}</small>`:''}</div>`}
function select(label,id,options,value,attrs=''){return `<div class="field"><label for="${id}">${label}</label><select id="${id}" ${attrs}><option value="">Seleccionar</option>${options.map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(x)}</option>`).join('')}</select></div>`}
const STEPS=['Agencia','Resultados','Pendientes','Activos','Documentos','Resumen'];
function form(){if(!current)return '';const readonly=current.status==='final'&&!editMode;const a=agency(current.agency);return heading(editMode?'CORRECCIÓN DE PRUEBA':readonly?'REGISTRO FINALIZADO':'NUEVO INVENTARIO',a?a.name:'Registro de inventario',`${current.agency?current.agency+' · ':''}${periodLabel(current.period)} · ${USERS.find(u=>u.id===current.auditor)?.name||'Auditor'}`,`<button class="btn" data-nav="records">${icon('list')} Registros</button>`)+`<div class="form-layout"><aside class="wizard-nav">${STEPS.map((s,i)=>`<button data-step="${i}" class="${step===i?'active':''}"><span class="stepnum">${i+1}</span><span class="steptext">${s}</span></button>`).join('')}<div class="wizard-note"><div class="progress"><div style="width:${(step+1)/6*100}%"></div></div><p class="note" style="margin-top:15px">${readonly?'Registro cerrado para el auditor.':editMode?'Los cambios requieren un motivo.':'El borrador se guarda automáticamente en este navegador.'}</p></div></aside><section class="panel"><div class="panelhead"><div><div class="eyebrow">PASO ${step+1} DE 6</div><h2>${STEPS[step]==='Resultados'?'Resultados del inventario':STEPS[step]==='Pendientes'?'Pendientes de regularización':STEPS[step]}</h2></div><span class="tag ${readonly?'green':'amber'}">${readonly?esc(syncLabel(current)):editMode?'En corrección':'Borrador'}</span></div><div class="panelbody"><div id="form-error" role="alert"></div><fieldset ${readonly?'disabled':''} style="border:0;padding:0;margin:0;min-width:0">${step===0?agencyForm():step===1?resultForm():step===2?pendingForm():step===3?assetForm():step===4?docsForm():reviewForm()}</fieldset><div class="save-status" id="save-status">${readonly?esc(syncLabel(current)):editMode?'Cambios sin aplicar hasta confirmar la corrección':storageOK?'Borrador guardado en este dispositivo':'No se pudo guardar el borrador'}</div><div class="formfoot"><button class="btn" ${step===0?'data-nav="records"':`data-step="${step-1}"`}>${step===0?'Volver':'Anterior'}</button><div class="toolbar">${readonly&&admin()?`<button class="btn" data-history="${current.id}">Historial</button><button class="btn primary" data-edit="${current.id}">Corregir</button>`:''}${step<5?`<button class="btn primary" data-step="${step+1}">Continuar ${icon('arrow')}</button>`:!readonly?`<button class="btn primary" id="finalize">${icon('check')}${editMode?'Guardar corrección':'Finalizar prueba'}</button>`:''}</div></div></div></section></div>`}
function agencyForm(){
 const a=agency(current.agency);
 const selectedCity=a?.city||current.selectedCity||'';
 const cities=[...new Set(AGENCIES.map(x=>x.city).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'es'));
 const agenciesInCity=selectedCity?AGENCIES.filter(x=>x.city===selectedCity).sort((a,b)=>a.name.localeCompare(b.name,'es')):[];
 return `<div class="fieldgrid"><div class="field full"><label for="city-filter">Ciudad *</label><select id="city-filter" ${canEdit()?'':'disabled'}><option value="">Selecciona primero una ciudad</option>${cities.map(city=>`<option value="${esc(city)}" ${city===selectedCity?'selected':''}>${esc(city)}</option>`).join('')}</select></div><div class="field full"><label for="agency">Agencia *</label><select id="agency" data-field="agency" ${selectedCity?'':'disabled'}><option value="">${selectedCity?'Selecciona una agencia':'Primero selecciona la ciudad'}</option>${agenciesInCity.map(x=>`<option value="${esc(x.id)}" ${x.id===current.agency?'selected':''}>${esc(x.id)} — ${esc(x.name)}</option>`).join('')}</select>${selectedCity?`<small>${agenciesInCity.length} agencias disponibles en ${esc(selectedCity)}</small>`:''}</div>${input('Fecha del inventario','date','date','El periodo corresponde al mismo mes de la visita.',{required:true})}${input('Periodo','period','month','Se determina desde la fecha del inventario.',{readonly:true})}<div class="field"><label for="auditor">Auditor responsable *</label><select id="auditor" data-field="auditor" ${canEdit()?'':'disabled'}><option value="">Selecciona un auditor</option>${USERS.filter(u=>u.role==='Auditor').map(u=>`<option value="${esc(u.id)}" ${u.id===current.auditor?'selected':''}>${esc(u.name)} · ${esc(u.city)}</option>`).join('')}</select><small>Solo auditores habilitados para agencias (columna F = Sí).</small></div></div>${a?`<div class="callout" style="margin-top:20px">${icon('pin')} <strong>${esc(a.city)}</strong><p style="margin:8px 0">${esc(a.address)}</p>${a.map?`<a href="${esc(a.map)}" target="_blank" rel="noopener">Abrir ubicación en Google Maps ↗</a>`:'<small>Ubicación sin enlace confirmado</small>'}</div>`:''}`;
}
function resultForm(){recordDefaults(current);return `<p class="note">Copia los importes totales del sistema. Los pendientes de regularización se registran por separado en el siguiente paso.</p><div class="fieldgrid">${input('Valor total de stock','stock','number','Total valorizado que figura en el sistema.',{required:true,money:true})}${input('Valor del faltante','short','number','No incluye los pendientes de regularización.',{required:true,money:true})}${input('Valor del sobrante','over','number','Registra 0 si no existe sobrante.',{required:true,money:true})}${input('Diferencias por ingresos de pedidos en COI','coi','number','Valor del pedido no incluido en el stock. Copia el importe del sistema; registra 0 si no existe.',{required:true,money:true})}${input('Deuda por recaudación','debt','number','Importe copiado del sistema.',{required:true,money:true})}<div class="full calcbox"><span>Porcentaje de faltante<br><small>Faltante ÷ valor del stock</small></span><strong id="pct">${percentage()}</strong></div></div><p class="note" style="margin-top:15px">COI se registra por separado. No se agrega al stock, al faltante ni a los pendientes; el porcentaje de faltante usa el stock copiado del sistema.</p>`}
function percentage(){return Number(current.stock)>0&&current.short!==''?`${(Number(current.short)/Number(current.stock)*100).toLocaleString('es-BO',{minimumFractionDigits:2,maximumFractionDigits:2})} %`:Number(current.stock)===0&&current.stock!==''?'Stock cero · revisar':'—'}
const pendingTotal=r=>Object.entries(r.pending||{}).reduce((n,[i,p])=>n+(i!=='10'&&p.selected?(Number(p.amount)||0):0),0);
const coiValue=r=>r.coi??(r.pending?.[10]?.selected?r.pending[10].amount:'0');
function pendingForm(){return `<p class="note">Selecciona cada categoría aplicable y copia su monto del sistema. Son faltantes adicionales aún no considerados para facturación. Si no existen, deja todas sin seleccionar.</p>${CATS.map(([name,area],i)=>{if(i===10)return '';const p=current.pending[i]||{};return `<div class="category"><div class="category-main"><input type="checkbox" id="cat${i}" data-cat="${i}" ${p.selected?'checked':''}><label for="cat${i}">${name}<small>Área responsable: ${area}</small></label>${p.selected?`<div class="field categoryamount"><label for="amount${i}" class="field-label">Monto (Bs) *</label><input id="amount${i}" data-amount="${i}" type="number" min="0.01" step="0.01" inputmode="decimal" value="${esc(p.amount??'')}"></div>`:''}</div>${p.selected&&i===11?`<div class="field other"><label for="other">Descripción de otro pendiente *</label><input id="other" data-other value="${esc(p.detail||'')}"></div>`:''}</div>`}).join('')}<div class="calcbox" style="margin-top:20px"><span>Total pendiente de regularización</span><strong id="pending-total">Bs ${money(pendingTotal(current))}</strong></div>`}
function assetFormBase(){const a=agency(current.agency);return `<h3>Activos logísticos · canastillos</h3><div class="fieldgrid">${input('Cantidad según sistema','cratesSystem','number','',{required:true,integer:true})}${input('Cantidad física contabilizada','cratesPhysical','number','',{required:true,integer:true})}<div class="full calcbox"><span>Diferencia: físico − sistema</span><strong id="crate-diff">${crateDiff()}</strong></div></div><h3 style="margin-top:28px">Activos comerciales ${a?`· ${a.assets.length} códigos`:''}</h3><p class="note">Verifica cada código. Las marcas del documento original no se cargaron como resultados de esta visita.</p>${a?a.assets.map(([code,desc])=>{const v=current.assets[code]||{};return `<div class="asset"><div class="asset-head"><strong>${code}</strong><span>${desc}</span></div><div class="fieldgrid">${select('Estado *','asset'+code,['Buen estado','Mal estado','No se encuentra en el lugar'],v.state,`data-asset="${code}"`)}<div class="field"><label for="obs${code}">Observación</label><input id="obs${code}" data-asset-note="${code}" value="${esc(v.note||'')}" placeholder="Detalle opcional"></div></div></div>`}).join('')+`<p class="note">Activos importados del catálogo maestro de noviembre. Verifica los códigos físicos durante la visita.</p>`:`<div class="callout warn">Selecciona la agencia en el paso 1 para cargar sus activos.</div>`}`}
function assetForm(){recordDefaults(current);return assetFormBase()+extraAssetsForm()}
function crateDiff(){if(current.cratesSystem===''||current.cratesPhysical==='')return '—';const n=Number(current.cratesPhysical)-Number(current.cratesSystem);return `${n>0?'+':''}${n} ${n<0?'faltantes':n>0?'sobrantes':'sin diferencia'}`}
function docsForm(){return `<p class="note">Verifica existencia y vigencia por separado. Si no tiene el documento, la vigencia se registra como “No aplica”.</p><div class="fieldgrid">${input('Nombre del responsable de la agencia','responsible','text','Referencia para la verificación del carnet sanitario.',{required:true,full:true})}</div>${DOCS.map((d,i)=>{const v=current.docs[i]||{};return `<div class="doc"><h3>${d}</h3><div class="fieldgrid">${select('¿Tiene el documento? *','has'+i,['Sí','No'],v.has,`data-doc-has="${i}"`)}${select('¿Está vigente? *','valid'+i,v.has==='No'?['No aplica']:['Sí','No','No verificado'],v.valid,`data-doc-valid="${i}" ${v.has==='No'?'disabled':''}`)}</div></div>`}).join('')}<div class="field" style="margin-top:20px"><label for="notes">Observaciones generales</label><textarea id="notes" rows="3" data-field="notes" placeholder="Hallazgos o aclaraciones de la visita">${esc(current.notes)}</textarea></div>`}
function reviewFormBase(){const r=recordDefaults(current),a=agency(r.agency);const line=(k,v)=>`<div class="reviewrow"><span>${esc(k)}</span><strong>${v}</strong></div>`;return `<p class="note">${r.status==='final'?'Consulta los datos actuales del registro.':'Revisa estos datos con el responsable de la agencia antes de finalizar y solicitar su firma.'}</p><h3>Agencia y visita</h3>${line('Agencia',esc((a?.id||'')+' · '+(a?.name||'Sin seleccionar')))}${line('Ciudad',esc(a?.city||'—'))}${line('Fecha / periodo',esc(r.date+' / '+periodLabel(r.period)))}${line('Auditor · solo WareIQ',esc(USERS.find(u=>u.id===r.auditor)?.name||'—'))}${line('Responsable de la agencia',esc(r.responsible||'—'))}<h3 class="summary-heading">Resultados del inventario</h3>${line('Valor del stock','Bs '+money(r.stock))}${line('Faltante','Bs '+money(r.short))}${line('Sobrante','Bs '+money(r.over))}${line('Porcentaje de faltante',percentage())}${line('Deuda por recaudación','Bs '+money(r.debt))}${line('Diferencias por ingresos de pedidos en COI','Bs '+money(coiValue(r)))}<h3 class="summary-heading">Pendientes de regularización</h3>${Object.entries(r.pending).filter(([i,p])=>i!=='10'&&p.selected).map(([i,p])=>line(CATS[i]?.[0]||'Pendiente','Bs '+money(p.amount)+(p.detail?'<br><small>'+esc(p.detail)+'</small>':''))).join('')||'<p class="note">Sin pendientes registrados.</p>'}${line('Total pendiente','Bs '+money(pendingTotal(r)))}<p class="note">Los pendientes no incluyen COI y se mantienen separados del faltante del inventario.</p><h3 class="summary-heading">Activos logísticos · canastillos</h3>${line('Cantidad según sistema',esc(r.cratesSystem))}${line('Cantidad física contabilizada',esc(r.cratesPhysical))}${line('Diferencia',esc(crateDiff()))}<h3 class="summary-heading">Activos comerciales asignados</h3>${(a?.assets||[]).map(([code,desc])=>line(code+' · '+desc,esc(r.assets[code]?.state||'Sin verificar')+(r.assets[code]?.note?'<br><small>'+esc(r.assets[code].note)+'</small>':''))).join('')}<h3 class="summary-heading">Activos encontrados fuera del listado</h3>${r.extraAssets.map(x=>line((x.noCode?'Sin código: '+x.codeReason:x.code)+' · '+x.description,esc(x.state)+(x.note?'<br><small>'+esc(x.note)+'</small>':''))).join('')||'<p class="note">Sin activos adicionales.</p>'}<h3 class="summary-heading">Documentos administrativos</h3>${DOCS.map((name,i)=>line(name,'Tiene: '+esc(r.docs[i]?.has||'Sin verificar')+' · Vigente: '+esc(r.docs[i]?.valid||'Sin verificar'))).join('')}${r.notes?'<h3 class="summary-heading">Observaciones generales</h3><p class="summary-notes">'+esc(r.notes)+'</p>':''}<div class="callout warn" style="margin-top:20px"><strong>Registro WareIQ</strong><p style="margin:7px 0 0">Los datos se guardan localmente y se sincronizan con Google Sheets cuando hay conexión.</p></div>${editMode?`<div class="field" style="margin-top:20px"><label for="reason">Motivo de la corrección *</label><textarea id="reason" rows="3" placeholder="Explica por qué cambias el registro"></textarea></div>`:''}`}
function reviewForm(){return reviewFormBase()+signatureForm()}
function validMoney(v){return typeof v!=='boolean'&&v!==null&&String(v??'').trim()!==''&&Number.isFinite(Number(v))&&Number(v)>=0&&Math.abs(Number(v)*100-Math.round(Number(v)*100))<0.000001}

function validSignedMoney(v){return typeof v!=='boolean'&&v!==null&&String(v??'').trim()!==''&&Number.isFinite(Number(v))&&Math.abs(Number(v)*100-Math.round(Number(v)*100))<0.000001}

function validateBase(upTo=5){const r=recordDefaults(current),a=agency(r.agency);
if(!a)return[0,'Selecciona una agencia.'];
const parsed=new Date(r.date+'T12:00:00Z');
if(!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||!Number.isFinite(parsed.getTime())||parsed.toISOString().slice(0,10)!==r.date||r.period!==r.date.slice(0,7))return[0,'Ingresa una fecha válida; el periodo debe corresponder al mes del inventario.'];
if(!USERS.some(u=>u.id===r.auditor&&u.role==='Auditor'))return[0,'Selecciona un auditor habilitado para agencias.'];
if(storeData.records.some(x=>x.id!==r.id&&x.agency===r.agency&&x.period===r.period))return[0,'Ya existe un registro para esta agencia y mes. Abre el registro existente desde Registros.'];
if(upTo<1)return null;
for(const [k,label]of [['stock','Valor total de stock'],['short','Valor del faltante'],['over','Valor del sobrante'],['debt','Deuda por recaudación'],['coi','Diferencias por ingresos de pedidos en COI']])
if(!(k==='coi'?validSignedMoney(r[k]):validMoney(r[k])))
return[1,label+': ingresa un importe igual o mayor a cero, con un máximo de dos decimales. Usa 0 si no existe importe.'];
if(upTo<2)return null;
for(const [i,p]of Object.entries(r.pending))if(p.selected){if(!CATS[i])return[2,'Revisa la categoría del pendiente.'];if(!validMoney(p.amount)||Number(p.amount)<=0)return[2,CATS[i][0]+': ingresa un monto mayor a cero con un máximo de dos decimales.'];if(i==='11'&&!p.detail?.trim())return[2,'Describe el pendiente seleccionado como “Otro”.'];}
if(upTo<3)return null;
for(const [k,label]of [['cratesSystem','Canastillos según sistema'],['cratesPhysical','Canastillos contabilizados']])if(!validMoney(r[k])||!Number.isSafeInteger(Number(r[k])))return[3,label+': ingresa una cantidad entera igual o mayor a cero.'];
for(const [code]of a.assets)if(!['Buen estado','Mal estado','No se encuentra en el lugar'].includes(r.assets[code]?.state))return[3,'Selecciona el estado del activo comercial '+code+'.'];
if(upTo<4)return null;
if(!r.responsible?.trim())return[4,'Registra el nombre del responsable de la agencia.'];
for(let i=0;i<DOCS.length;i++){const d=r.docs[i];if(!['Sí','No'].includes(d?.has))return[4,DOCS[i]+': indica si tiene el documento.'];if(!(d.has==='No'?['No aplica']:['Sí','No','No verificado']).includes(d.valid))return[4,DOCS[i]+': verifica la vigencia; “No aplica” solo corresponde cuando no tiene el documento.'];}
return null}
function validate(upTo=5){const errors=[validateBase(upTo),validateAdditions(upTo)].filter(Boolean);return errors.sort((a,b)=>a[0]-b[0])[0]||null}
function showValidationError(e){step=e[0];render();document.getElementById('form-error').innerHTML=`<div class="error">${esc(e[1])}</div>`;document.getElementById('form-error').setAttribute('tabindex','-1');document.getElementById('form-error').focus?.();window.scrollTo(0,0)}
function goToStep(target){if(!Number.isInteger(target)||target<0||target>=STEPS.length)return false;if(target>step&&canEdit()){const e=validate(target-1);if(e){showValidationError(e);return false}}if(current.status==='draft'&&!editMode&&!saveCurrent())return false;step=target;render();window.scrollTo(0,0);return true}


const WAREIQ_API_URL =
  'https://script.google.com/macros/s/AKfycbySKu0dBHPU-_edsVACsN9Ko7xJgdKQFXJz767RrE5n1tCIHBzZsZpTjevGX44A62DEOQ/exec';

async function enviarInventarioGoogleSheets(registro) {
  const respuesta = await fetch(WAREIQ_API_URL, {
    method: 'POST',
    mode: 'no-cors',
    headers: {
      'Content-Type': 'text/plain;charset=utf-8'
    },
    body: JSON.stringify({
      tipo: 'inventario',
      registro: registro
    })
  });

  return {
    enviado: true,
    confirmado: false
  };
}


// Sincronizacion WareIQ: el GET con callback permite verificar la revision
// desde GitHub Pages sin depender de leer un fetch no-cors.
const WAREIQ_SYNC_INTERVAL_MS = 90000;
const WAREIQ_SYNC_TIMEOUT_MS = 15000;
const syncBusy = new Set();
let syncTimer = null;
function syncInfo(r) {
  if (!r.sync || typeof r.sync !== 'object') r.sync = {state:'pending',revision:0};
  if (r.status==='final' && Number(r.sync.revision||0)<Number(r.revision||1) && r.sync.state==='synced') r.sync.state='pending';
  return r.sync;
}
function syncLabel(r) {
  if (r.status!=='final') return 'Borrador';
  const s=syncInfo(r);
  if (s.state==='synced' && Number(s.revision)>=Number(r.revision||1)) return 'Sincronizado';
  if (s.state==='error') return 'Error de sincronización';
  return 'Pendiente de envío';
}
function syncTag(r) {
  const label=syncLabel(r);
  return `<span class="tag ${label==='Sincronizado'?'green':label==='Error de sincronización'?'':'amber'}">${esc(label)}</span>`;
}
function consultarInventarioGoogleSheets(id) {
  return new Promise((resolve,reject)=>{
    if(!navigator.onLine) {reject(new Error('Sin internet'));return;}
    const callback='wareiq_cb_'+Math.random().toString(36).slice(2);
    const script=document.createElement('script');
    let finished=false;
    const cleanup=()=>{delete window[callback];script.remove();clearTimeout(timeout)};
    const finish=(error,data)=>{if(finished)return;finished=true;cleanup();error?reject(error):resolve(data)};
    window[callback]=data=>finish(null,data);
    script.onerror=()=>finish(new Error('No se pudo consultar Google Sheets'));
    const timeout=setTimeout(()=>finish(new Error('Tiempo de consulta agotado')),WAREIQ_SYNC_TIMEOUT_MS);
    script.src=WAREIQ_API_URL+'?id='+encodeURIComponent(id)+'&callback='+encodeURIComponent(callback)+'&_='+Date.now();
    document.head.appendChild(script);
  });
}
function guardarEstadoSync(id,revision,state,error='') {
  const r=storeData.records.find(x=>x.id===id);
  if(!r)return;
  r.sync={state,revision:state==='synced'?revision:Number(r.sync?.revision||0),error,checkedAt:new Date().toISOString()};
  persist();
  if(page==='records'||page==='home')render();
}
async function sincronizarInventario(r,force=false) {
  if(!r || r.status!=='final' || syncBusy.has(r.id))return;
  const id=r.id,revision=Number(r.revision||1);
  if(syncInfo(r).state==='synced' && Number(r.sync.revision)>=revision)return;
  if(!navigator.onLine){guardarEstadoSync(id,revision,'pending');return;}
  syncBusy.add(id);
  try {
    // Primero comprobar si el servidor ya recibio el registro.
    let estado=await consultarInventarioGoogleSheets(id);
    if(!estado?.ok)throw new Error(estado?.error||'Consulta no confirmada');
    if(estado.encontrado && Number(estado.revision)>=revision){
      guardarEstadoSync(id,revision,'synced');return;
    }
    if(estado.encontrado && Number(estado.revision)!==revision-1){
      throw new Error('La revision de la base central no coincide');
    }
    // Solo enviar cuando la consulta confirmó que falta esta revision.
    guardarEstadoSync(id,revision,'pending');
    await enviarInventarioGoogleSheets(JSON.parse(JSON.stringify(r)));
    // La respuesta de no-cors no confirma nada: volver a consultar.
    let confirmado=false;
    for(let i=0;i<3;i++){
      await new Promise(resolve=>setTimeout(resolve,1200*(i+1)));
      estado=await consultarInventarioGoogleSheets(id);
      if(estado?.ok && estado.encontrado && Number(estado.revision)>=revision){confirmado=true;break;}
      if(estado?.ok===false)throw new Error(estado.error||'Error del servidor');
    }
    if(!confirmado)throw new Error('Google Sheets todavía no confirmó el registro');
    guardarEstadoSync(id,revision,'synced');
  } catch(e){
    console.warn('WareIQ sincronización:',id,e);
    guardarEstadoSync(id,revision,navigator.onLine?'error':'pending',String(e.message||e));
  } finally {syncBusy.delete(id);}
}
function sincronizarPendientes(){
  if(!navigator.onLine)return;
  for(const r of storeData.records){
    if(r.status==='final' && syncInfo(r).state!=='synced') sincronizarInventario(r);
  }
}
function finalizeRecord(){if(current.status==='final'&&!editMode)return;const e=validate();if(e){showValidationError(e);return}if(editMode){if(!admin()){toast('El perfil auditor no puede corregir registros finalizados.');return}const reason=document.getElementById('reason')?.value.trim();if(!reason){toast('Escribe el motivo de la corrección.');return}const before=storeData.records.find(r=>r.id===current.id);const changes=[];for(const k of ['agency','date','period','stock','short','over','debt','coi','cratesSystem','cratesPhysical','responsible','pending','assets','docs','notes','extraAssets'])if(JSON.stringify(k==='extraAssets'?(before[k]||[]):before[k])!==JSON.stringify(current[k]))changes.push({field:k,before:before[k],after:current[k]});if(!changes.length){toast('No hay cambios para guardar.');return}current.revision=(before.revision||1)+1;current.history.push({at:new Date().toISOString(),by:user().id,reason,changes});}else{current.revision=1;if(current.signature.mode==='omitted'){current.signature.capturedAt=new Date().toISOString();current.signature.snapshot=inventorySnapshot(current);current.signature.version=1}current.status='final';current.finalized=new Date().toISOString();current.history.push({at:current.finalized,by:user().id,reason:'Finalización del registro de prueba',changes:[]})}


const wasEdit = editMode;

if (saveCurrent()) {
  const registroParaEnviar = JSON.parse(
    JSON.stringify(current)
  );

  nav('records');

  toast('Registro guardado. Intentando enviar a Google Sheets...');

  guardarEstadoSync(registroParaEnviar.id, registroParaEnviar.revision, 'pending');
  sincronizarInventario(registroParaEnviar).then(() => {
    const r=storeData.records.find(x=>x.id===registroParaEnviar.id);
    toast(r?.sync?.state==='synced'?'Inventario confirmado en Google Sheets.':'Inventario guardado localmente. Revisa su estado en Registros.');
  });
}
}
                          
                          
function canDeleteRecord(r){return !!r&&(admin()||r.auditor===user().id)}
function deleteRecord(id){const r=storeData.records.find(r=>r.id===id);if(!canDeleteRecord(r))return false;const before=storeData.records;storeData.records=before.filter(r=>r.id!==id);if(!persist()){storeData.records=before;return false}if(current?.id===id){current=null;editMode=false}page='records';render();toast('Registro eliminado solo de este dispositivo. Si estaba sincronizado, permanece en Google Sheets.');return true}
function requestDeleteRecord(id){const r=storeData.records.find(r=>r.id===id);if(!canDeleteRecord(r))return;const dialog=document.createElement('dialog');dialog.setAttribute('aria-labelledby','delete-title');dialog.innerHTML=`<h2 id="delete-title">Eliminar registro de prueba</h2><p><strong>${esc(r.agency||'Sin agencia')} · ${esc(agency(r.agency)?.name||'Borrador')}</strong><br>${esc(periodLabel(r.period))} · ${r.status==='final'?'Finalizado':'Borrador'}</p><p>Se eliminarán los datos, la firma y el historial de este registro guardado en este navegador. Esto solo elimina la copia de este navegador; NO elimina el inventario ya sincronizado en Google Sheets. La agencia y su catálogo de activos se conservarán. Podrás registrar nuevamente esta agencia y mes.</p><p class="note">Si deseas conservar la prueba, cancela y descarga un respaldo en «Base de prueba».</p><div class="toolbar"><button class="btn" data-cancel-delete autofocus>Cancelar</button><button class="btn primary" data-confirm-delete>Eliminar registro</button></div>`;document.body.append(dialog);dialog.querySelector('[data-cancel-delete]').onclick=()=>dialog.close();dialog.querySelector('[data-confirm-delete]').onclick=()=>{if(deleteRecord(id))dialog.close()};dialog.onclose=()=>dialog.remove();dialog.showModal()}
function deleteRecordButton(r){return canDeleteRecord(r)?` <button class="btn small" data-delete-record="${esc(r.id)}" aria-label="Eliminar registro de ${esc(r.agency||'agencia sin seleccionar')}">Eliminar prueba</button>`:''}
function recordTable(rs){return `<div class="tablewrap desktop"><table><thead><tr><th>Agencia / periodo</th><th>Faltante</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${rs.map(r=>`<tr><td><strong>${r.agency||'Sin agencia'} · ${esc(agency(r.agency)?.name||'Nuevo registro')}</strong><small class="text-muted">${periodLabel(r.period)}</small></td><td>Bs ${money(r.short)}</td><td><span class="tag ${r.status==='final'&&syncLabel(r)==='Sincronizado'?'green':'amber'}">${r.status==='final'?esc(syncLabel(r)):'Borrador'}</span></td><td><button class="btn small" data-open="${r.id}">${r.status==='final'?'Consultar':'Continuar'}</button> ${r.status==='final'&&admin()?`<button class="btn small" data-edit="${r.id}">Corregir</button>`:''}${deleteRecordButton(r)}</td></tr>`).join('')}</tbody></table></div><div class="recordcards">${rs.map(r=>`<div class="recordcard"><div class="head"><strong>${r.agency||'Sin agencia'} · ${esc(agency(r.agency)?.name||'Nuevo registro')}</strong><span class="tag ${r.status==='final'&&syncLabel(r)==='Sincronizado'?'green':'amber'}">${r.status==='final'?esc(syncLabel(r)):'Borrador'}</span></div><p class="sub">${periodLabel(r.period)} · Bs ${money(r.short)} de faltante</p><div class="card-actions"><button class="btn small" data-open="${r.id}">${r.status==='final'?'Consultar':'Continuar'}</button>${r.status==='final'&&admin()?`<button class="btn small" data-edit="${r.id}">Corregir</button>`:''}${deleteRecordButton(r)}</div></div>`).join('')}</div>`}
function records(){let rs=visibleRecords().slice().sort((a,b)=>b.updated.localeCompare(a.updated));if(recordFilter)rs=rs.filter(r=>r.status===recordFilter);return heading('HISTÓRICO LOCAL',admin()?'Registros de inventario':'Mis registros','Un registro por agencia y mes. Usa «Eliminar prueba» para liberar una agencia y repetir la demostración.',`<button class="btn primary" data-new>${icon('plus')} Nuevo</button>`)+`<section class="panel"><div class="panelhead"><h2>${rs.length} ${rs.length===1?'registro':'registros'}</h2><select class="filter" id="record-filter" style="width:auto" aria-label="Filtrar por estado"><option value="">Todos los estados</option><option value="draft" ${recordFilter==='draft'?'selected':''}>Borradores</option><option value="final" ${recordFilter==='final'?'selected':''}>Finalizados locales</option></select></div>${rs.length?recordTable(rs):empty('No hay registros en esta vista','Crea un inventario o cambia el perfil de prueba para consultar sus registros.')}</section><div class="callout">${icon('shield')} ${admin()?'Puedes corregir registros finalizados. Cada corrección guarda el autor, la fecha, el motivo y los valores modificados.':'Después de finalizar, las correcciones solo están disponibles en los perfiles de supervisora y socio. Los perfiles de este piloto son simulados.'}</div>`}
function agencies(){return heading('DIRECTORIO','Agencias y activos','${AGENCIES.length} agencias y ${AGENCIES.reduce((n,a)=>n+a.assets.length,0)} activos incorporados desde el Excel.')+AGENCIES.map(a=>`<section class="panel"><div class="panelhead"><div><h2>${a.name}</h2><p class="sub">${a.id} · ${a.city} · ${a.assets.length} activos</p></div><button class="btn primary small" data-new="${a.id}">Registrar ${icon('arrow')}</button></div><div class="panelbody"><div class="toolbar">${a.map?`<a class="btn small" href="${esc(a.map)}" target="_blank" rel="noopener">${icon('pin')} Google Maps ↗</a>`:""}<span class="note">${a.address}</span></div><details><summary>Consultar códigos y documento de origen</summary><div class="tablewrap"><table><thead><tr><th>Código</th><th>Descripción</th></tr></thead><tbody>${a.assets.map(([c,d])=>`<tr><td>${c}</td><td style="white-space:normal">${d}</td></tr>`).join('')}</tbody></table></div></details></div></section>`).join('')}
function dataView(){if(!admin())return heading('FUENTE DE DATOS','Base de prueba','Acceso administrativo simulado.')+`<div class="callout">Cambia al perfil de supervisora o socio en “Piloto y perfiles” para probar la consulta completa y las exportaciones.</div>`;const rs=finalized();return heading('ANÁLISIS Y EXPORTACIÓN','Base de prueba','Solo registros finalizados. Las exportaciones se generan desde este navegador.')+`<div class="settings-grid"><section class="panel"><div class="panelhead"><h2>Fuente interna · WareIQ</h2><span class="tag">Con trazabilidad</span></div><div class="panelbody"><p class="note">Incluye identificador y nombre del auditor. Descarga tablas separadas de inventarios, pendientes, activos, documentos y estado de firma para relacionarlas mediante el ID de inventario.</p><button class="btn primary" data-export="wareiq">${icon('download')} Exportar tablas CSV</button></div></section><section class="panel"><div class="panelhead"><h2>Fuente · Compañía</h2><span class="tag green">Sin auditor</span></div><div class="panelbody"><p class="note">Excluye identidad, correo del auditor, responsable de agencia y notas libres. Entrega datos estructurados y estado de firma; excluye nombre del firmante y motivos libres.</p><button class="btn" data-export="company">${icon('download')} Exportar tablas CSV</button></div></section></div><section class="panel"><div class="panelhead"><h2>${rs.length} registros para análisis</h2><span class="tag">Todos los periodos</span></div>${rs.length?`<div class="tablewrap"><table><thead><tr><th>Periodo</th><th>Agencia</th><th>Stock Bs</th><th>Faltante Bs</th><th>% faltante</th><th>Pendientes Bs</th><th>COI Bs</th><th>Auditor · WareIQ</th><th>Historial</th></tr></thead><tbody>${rs.map(r=>`<tr><td>${r.period}</td><td>${r.agency}</td><td>${money(r.stock)}</td><td>${money(r.short)}</td><td>${Number(r.stock)>0?(Number(r.short)/Number(r.stock)*100).toFixed(2)+' %':'Revisar'}</td><td>${money(pendingTotal(r))}</td><td>${money(coiValue(r))}</td><td>${esc(USERS.find(u=>u.id===r.auditor)?.name)}</td><td><button class="btn small" data-history="${r.id}">Ver</button></td></tr>`).join('')}</tbody></table></div>`:empty('Aún no hay datos finalizados','Finaliza una prueba para revisar los cálculos y descargar las tablas.')}<div class="panelbody note">COI corresponde a pedidos no incluidos en el stock y se presenta por separado de los pendientes. El porcentaje global debe calcularse como suma de faltantes ÷ suma de stock, no como promedio de porcentajes.</div></section><div class="callout warn">Estas descargas permiten probar la estructura del BI. No existe todavía una conexión automática a Power BI, Google Drive ni a la plataforma WareIQ.</div>`}
function settings(){return heading('CONFIGURACIÓN DE LA PRUEBA','Tu espacio piloto','Prueba el recorrido con distintos perfiles, desde un solo dispositivo.')+`<div class="settings-grid"><section class="panel"><div class="panelhead"><h2>Perfiles ficticios</h2><span class="tag amber">Simulados</span></div><div class="panelbody"><p class="note">Este selector sirve para evaluar permisos en la interfaz. No es autenticación real ni protege una base compartida.</p>${USERS.map(u=>`<label class="persona ${u.id===user().id?'selected':''}"><input type="radio" name="persona" value="${u.id}" ${u.id===user().id?'checked':''}><span><strong>${u.name} · ${u.role}</strong><small>${u.id} · ${u.email}</small></span></label>`).join('')}</div></section><div><section class="panel"><div class="panelhead"><h2>Guardado y respaldo</h2></div><div class="panelbody"><div class="reviewrow"><span>Destino de los registros</span><strong>Este navegador</strong></div><div class="reviewrow"><span>Base compartida</span><strong>Google Sheets · conectado</strong></div><div class="reviewrow"><span>Conexión del dispositivo</span><strong>${navigator.onLine?'Disponible':'Sin internet'}</strong></div><div class="reviewrow"><span>Archivos para abrir sin conexión</span><strong id="offline-status">${offlineReady?'Preparados en este navegador':'Comprobando / aún no preparados'}</strong></div><p class="note" style="margin-top:17px">Abre primero con internet. Para probar: guarda un borrador, activa modo avión y vuelve a abrir. La apertura sin conexión también depende del acceso privado del sitio. No borres los datos del navegador antes de respaldar.</p><div class="toolbar"><button class="btn" id="backup">${icon('download')} Descargar respaldo</button><button class="btn" id="install">Instalar / acceso directo</button></div></div></section><div class="callout"><strong>Alcance de esta versión</strong><p style="margin:8px 0 0">Incluye formulario, cálculos, histórico local y correcciones simuladas. Sin cuentas reales ni autenticación; los perfiles son seleccionables. Con envío a Google Sheets. Identidad visual basada en el logo de WareIQ proporcionado.</p></div></div></div>`}
function openRecord(id,edit=false){const r=storeData.records.find(r=>r.id===id);if(!r||(!admin()&&r.auditor!==user().id))return;if(edit&&!admin())return;current=recordDefaults(structuredClone(r));editMode=edit;page='form';step=edit?1:r.status==='final'?5:0;render();window.scrollTo(0,0)}
function bind(){document.getElementById('city-filter')?.addEventListener('change',e=>{if(!canEdit())return;current.selectedCity=e.target.value;current.agency='';current.assets={};current.extraAssets=[];saveIfDraft();render()});document.querySelectorAll('[data-delete-record]').forEach(b=>b.onclick=()=>requestDeleteRecord(b.dataset.deleteRecord));document.getElementById('theme-select')?.addEventListener('change',e=>applyTheme(e.target.value));document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=e=>{e.preventDefault();nav(b.dataset.nav)});document.querySelectorAll('[data-new]').forEach(b=>b.onclick=()=>newRecord(b.dataset.new));document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{goToStep(Number(b.dataset.step))});document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openRecord(b.dataset.open));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openRecord(b.dataset.edit,true));document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>showHistory(b.dataset.history));document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>exportTables(b.dataset.export));document.querySelectorAll('[name=persona]').forEach(b=>b.onchange=()=>{storeData.user=b.value;persist();render();toast('Perfil de prueba cambiado.')});
 document.querySelectorAll('[data-field]').forEach(el=>el.oninput=()=>{if(!canEdit())return;const k=el.dataset.field;if(k==='agency'){if(current.agency!==el.value){current.assets={};current.extraAssets=[];current.agency=el.value;saveIfDraft();render();return}}else current[k]=el.value;if(k==='date'){current.period=el.value.slice(0,7);document.getElementById('period').value=current.period}saveIfDraft();if(document.getElementById('pct'))document.getElementById('pct').textContent=percentage();if(document.getElementById('crate-diff'))document.getElementById('crate-diff').textContent=crateDiff()});
 document.querySelectorAll('[data-cat]').forEach(el=>el.onchange=()=>{if(!canEdit())return;const k=el.dataset.cat;current.pending[k]={...(current.pending[k]||{amount:'',detail:''}),selected:el.checked};saveIfDraft();render()});document.querySelectorAll('[data-amount]').forEach(el=>el.oninput=()=>{if(!canEdit())return;current.pending[el.dataset.amount].amount=el.value;saveIfDraft();document.getElementById('pending-total').textContent='Bs '+money(pendingTotal(current))});document.querySelector('[data-other]')?.addEventListener('input',e=>{if(!canEdit())return;current.pending[11].detail=e.target.value;saveIfDraft()});
 for(const [attr,key]of [['asset','state'],['asset-note','note']])document.querySelectorAll(`[data-${attr}]`).forEach(el=>el.addEventListener(key==='state'?'change':'input',()=>{if(!canEdit())return;const code=el.getAttribute('data-'+attr);current.assets[code]={...(current.assets[code]||{}),[key]:el.value};saveIfDraft()}));document.querySelectorAll('[data-doc-has]').forEach(el=>el.onchange=()=>{if(!canEdit())return;const i=el.dataset.docHas;current.docs[i]={has:el.value,valid:el.value==='No'?'No aplica':''};saveIfDraft();render()});document.querySelectorAll('[data-doc-valid]').forEach(el=>el.onchange=()=>{if(!canEdit())return;const i=el.dataset.docValid;current.docs[i]={...(current.docs[i]||{}),valid:el.value};saveIfDraft()});document.getElementById('finalize')?.addEventListener('click',finalizeRecord);document.getElementById('record-filter')?.addEventListener('change',e=>{recordFilter=e.target.value;render()});document.getElementById('backup')?.addEventListener('click',()=>{const records=visibleRecords();download('wareiq-respaldo-'+localdate()+'.json',JSON.stringify({version:1,exported:new Date().toISOString(),scope:admin()?'administrativo':'auditor',records},null,2),'application/json');toast('Respaldo descargado. Consérvalo en un lugar seguro.')});document.getElementById('install')?.addEventListener('click',async()=>{if(promptInstall){await promptInstall.prompt();promptInstall=null}else toast('En Chrome de Android: menú ⋮ → Añadir a pantalla de inicio o Instalar aplicación.')});}
function canEdit(){return current&&(current.status==='draft'||editMode&&admin())}
function saveIfDraft(){if(current.status==='draft'&&!editMode){const ok=saveCurrent();const s=document.getElementById('save-status');if(s)s.textContent=ok?'Borrador guardado en este dispositivo':'No se pudo guardar'}}
function download(name,text,type='text/csv;charset=utf-8'){const blob=new Blob([text],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
const csv=rows=>'\uFEFF'+rows.map(row=>row.map(v=>{let s=String(v??'');if(/^[=+@\-]/.test(s)&&typeof v!=='number')s="'"+s;return '"'+s.replaceAll('"','""')+'"'}).join(';')).join('\r\n');
function exportTables(scope){if(!admin())return;const rs=finalized();if(!rs.length){toast('Finaliza un registro antes de exportar.');return}const company=scope==='company';const main=[['InventarioID','Periodo','Fecha','AgenciaCodigo','AgenciaNombre','Ciudad','StockBs','FaltanteBs','SobranteBs','PorcentajeFaltante','PendientesBs','COIBs','DeudaRecaudacionBs','CanastillosSistema','CanastillosFisicos','DiferenciaCanastillos',...company?[]:['AuditorID','AuditorNombre','AuditorCorreo']]];
const pending=[['InventarioID','Categoria','AreaResponsable','MontoBs',...company?[]:['DescripcionOtro']]],assets=[['InventarioID','CodigoActivo','Descripcion','Estado','Procedencia','RevisionAdministrativa',...company?[]:['Observacion','MotivoSinCodigo']]],docs=[['InventarioID','Documento','Tiene','Vigente']],signatures=[['InventarioID','EstadoFirma','FechaCaptura','VersionFirmada','VersionActual','DatosCoinciden',...company?[]:['Firmante','Cargo','MotivoSinFirma']]];for(const r of rs){const a=agency(r.agency),u=USERS.find(u=>u.id===r.auditor);main.push([r.id,r.period,r.date,r.agency,a.name,a.city,Number(r.stock),Number(r.short),Number(r.over),Number(r.stock)>0?Number(r.short)/Number(r.stock):'',pendingTotal(r),Number(coiValue(r)),Number(r.debt),Number(r.cratesSystem),Number(r.cratesPhysical),Number(r.cratesPhysical)-Number(r.cratesSystem),...company?[]:[r.auditor,u?.name,u?.email]]);for(const [i,p]of Object.entries(r.pending))if(i!=='10'&&p.selected)pending.push([r.id,CATS[i][0],CATS[i][1],Number(p.amount),...company?[]:[p.detail||'']]);for(const [code,desc]of a.assets)assets.push([r.id,code,desc,r.assets[code]?.state,'Listado asignado','No aplica',...company?[]:[r.assets[code]?.note||'','']]);for(const x of r.extraAssets||[])assets.push([r.id,x.noCode?'Sin código identificable':x.code,x.description,x.state,'Encontrado fuera del listado',x.review||'Pendiente de revisión',...company?[]:[x.note||'',x.codeReason||'']]);signatures.push([r.id,signatureLabel(r),r.signature?.capturedAt||'',r.signature?.version||'',r.revision||1,r.signature?.mode==='signed'?(signatureMatches(r)?'Sí':'No'):'No aplica',...company?[]:[r.signature?.name||'',r.signature?.role||'',r.signature?.reason||'']]);DOCS.forEach((d,i)=>docs.push([r.id,d,r.docs[i]?.has,r.docs[i]?.valid]));}const tables=[['inventarios',main],['pendientes',pending],['activos',assets],['documentos',docs],['firmas',signatures]];showExportDialog(tables,scope)}
function showExportDialog(tables,scope){const dialog=document.createElement('dialog');dialog.innerHTML=`<h2>Exportar fuente ${scope==='company'?'Compañía':'WareIQ'}</h2><p class="note">Descarga cada tabla. En Power BI se relacionan por InventarioID. Los importes de inventarios no deben repetirse al combinar tablas de detalle.</p><div class="toolbar">${tables.map(([name],i)=>`<button class="btn" data-download-table="${i}">${icon('download')} ${name}.csv</button>`).join('')}</div><button class="btn" style="margin-top:20px" data-close>Cerrar</button>`;document.body.append(dialog);dialog.querySelectorAll('[data-download-table]').forEach(b=>b.onclick=()=>{const[n,rows]=tables[Number(b.dataset.downloadTable)];download(`${scope}-${n}-${localdate()}.csv`,csv(rows))});dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();dialog.showModal()}
const fieldNames={agency:'Agencia',date:'Fecha',period:'Periodo',stock:'Stock Bs',short:'Faltante Bs',over:'Sobrante Bs',debt:'Deuda recaudación Bs',cratesSystem:'Canastillos sistema',cratesPhysical:'Canastillos físicos',responsible:'Responsable de agencia',pending:'Pendientes',assets:'Activos',docs:'Documentos',notes:'Observaciones',coi:'Diferencias COI Bs',extraAssets:'Activos encontrados fuera del listado'};
function pretty(v){return typeof v==='object'?JSON.stringify(v):String(v??'Vacío')}
function showHistory(id){if(!admin())return;const r=storeData.records.find(r=>r.id===id);const d=document.createElement('dialog');d.innerHTML=`<h2>Historial del registro</h2><p class="note">${r.agency} · ${periodLabel(r.period)} · Solo WareIQ</p>${r.history.map(h=>`<div class="history-item"><strong>${esc(USERS.find(u=>u.id===h.by)?.name)} · ${dt(h.at)}</strong><p style="margin:5px 0">${esc(h.reason)}</p>${h.changes.length?`<ul>${h.changes.map(c=>`<li><b>${fieldNames[c.field]}</b><br>Antes: ${esc(pretty(c.before))}<br>Después: ${esc(pretty(c.after))}</li>`).join('')}</ul>`:'<small>Autor original: '+esc(r.auditor)+'</small>'}</div>`).join('')}<button class="btn" style="margin-top:20px" data-close>Cerrar</button>`;document.body.append(d);d.querySelector('[data-close]').onclick=()=>d.close();d.onclose=()=>d.remove();d.showModal()}
// Field observations and the agency representative's signature stay with the inventory.
const BUSINESS_FIELDS=['agency','date','period','stock','short','over','debt','coi','cratesSystem','cratesPhysical','responsible','pending','assets','docs','notes'];
const makeId=()=>('randomUUID'in crypto?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join(''));
function recordDefaults(r){if(r.coi===undefined){r.coi=r.pending?.[10]?.selected?(r.pending[10].amount??''):'0';}if(r.pending)delete r.pending[10];r.extraAssets??=[];r.signature??={mode:'',name:r.responsible||'',role:'Responsable de la agencia',reason:'',points:[],image:'',capturedAt:'',snapshot:null};r.history??=[];return r}
function inventorySnapshot(r){const data={};for(const key of BUSINESS_FIELDS)data[key]=structuredClone(r[key]??'');data.agencyLabel=structuredClone(agency(r.agency)||{});data.assignedAssets=structuredClone(agency(r.agency)?.assets||[]);data.extraAssets=(r.extraAssets||[]).map(a=>({id:a.id,code:a.code,noCode:!!a.noCode,codeReason:a.codeReason,description:a.description,state:a.state,note:a.note}));data.signer={name:r.signature?.name||'',role:r.signature?.role||''};return data}
function signatureMatches(r){return !!r.signature?.snapshot&&JSON.stringify(r.signature.snapshot)===JSON.stringify(inventorySnapshot(r))}
function signatureLabel(r){if(r.signature?.mode==='signed')return signatureMatches(r)?'Firmado':'Firma de versión anterior';if(r.signature?.mode==='omitted')return 'Sin firma · motivo registrado';return r.status==='final'?'Registro anterior a la captura de firmas':'Pendiente de firma o motivo'}
function extraAssetsForm(){const a=agency(current.agency),editable=canEdit();return `<section class="extra-assets-section"><div class="extra-heading"><div><h3>Activos encontrados fuera del listado</h3><p class="note">Registra equipos presentes en la agencia que no aparecen en el listado asignado. No se agregan automáticamente al catálogo.</p></div>${editable?`<button type="button" class="btn" id="add-extra-asset" ${a?'':'disabled'}>${icon('plus')} Agregar activo encontrado</button>`:''}</div>${(current.extraAssets||[]).length?current.extraAssets.map((x,i)=>`<div class="extra-asset"><div class="extra-heading"><strong>Activo adicional ${i+1}</strong><span class="tag amber">${esc(x.review||'Pendiente de revisión')}</span>${editable?`<button type="button" class="btn small" data-remove-extra="${i}">Quitar de este registro</button>`:''}</div><div class="fieldgrid"><div class="field"><label for="extra-code-${i}">Código del activo ${x.noCode?'':'*'}</label><input id="extra-code-${i}" data-extra-index="${i}" data-extra-key="code" value="${esc(x.code||'')}" ${x.noCode?'disabled':''} placeholder="Código físico del equipo"><label class="checkline" for="extra-nocode-${i}"><input id="extra-nocode-${i}" type="checkbox" data-extra-nocode="${i}" ${x.noCode?'checked':''}> No tiene código o no es legible</label></div><div class="field"><label for="extra-description-${i}">Descripción *</label><input id="extra-description-${i}" data-extra-index="${i}" data-extra-key="description" value="${esc(x.description||'')}" placeholder="Tipo, marca o modelo del equipo"></div>${x.noCode?`<div class="field full"><label for="extra-codereason-${i}">Motivo por el que no se identifica el código *</label><input id="extra-codereason-${i}" data-extra-index="${i}" data-extra-key="codeReason" value="${esc(x.codeReason||'')}" placeholder="Por ejemplo: placa ilegible"></div>`:''}${select('Estado *','extra-state-'+i,['Buen estado','Mal estado'],x.state,`data-extra-index="${i}" data-extra-key="state"`)}<div class="field"><label for="extra-note-${i}">Observación / ubicación dentro de la agencia</label><input id="extra-note-${i}" data-extra-index="${i}" data-extra-key="note" value="${esc(x.note||'')}" placeholder="Detalle opcional"></div>${admin()&&editMode?select('Revisión administrativa','extra-review-'+i,['Pendiente de revisión','Validado para regularización','Observado'],x.review||'Pendiente de revisión',`data-extra-index="${i}" data-extra-key="review"`):''}</div></div>`).join(''):`<p class="note extra-empty">No se registraron equipos adicionales.</p>`}</section>`}
function signatureForm(){const r=recordDefaults(current),s=r.signature,frozen=r.status==='final',signed=s.mode==='signed',omitted=s.mode==='omitted';return `<section class="signature-section"><h3>Firma del responsable de la agencia</h3><p class="note">Revisa el resumen con el responsable antes de solicitar su firma. Esta firma corresponde a los datos de ese momento.</p>${frozen?`<span class="tag ${signatureMatches(r)?'green':'amber'}">${signatureLabel(r)}</span>${s.mode?`<p class="note" style="margin-top:12px">${signed?`Firmante: <strong>${esc(s.name)}</strong> · ${esc(s.role)}<br>Capturada: ${esc(dt(s.capturedAt))} · versión ${s.version||1}`:`Motivo: <strong>${esc(s.reason)}</strong>`}</p>`:''}${signed&&s.image?`<img class="signature-preview" src="${s.image}" alt="Firma del responsable de la agencia ${esc(s.name)}"><a class="btn small" href="${s.image}" download="firma-${esc(r.agency)}-${esc(r.period)}-v${s.version||1}.png">${icon('download')} Descargar firma PNG</a>${!signatureMatches(r)?`<details><summary>Ver datos originales asociados a esta firma</summary>${signedSnapshotView(s.snapshot)}</details>`:''}`:''}${editMode?`<div class="callout warn" style="margin-top:15px">La firma o el motivo original se conservan. Si corriges los datos del inventario, la firma no se presentará como conformidad de la versión corregida.</div>`:''}`:`${select('Registro de firma *','signature-mode',['Firmar','No se obtuvo firma'],signed?'Firmar':omitted?'No se obtuvo firma':'','data-signature-mode')}${signed?`<div class="fieldgrid" style="margin-top:18px"><div class="field"><label for="signature-name">Nombre del responsable que firma *</label><input id="signature-name" data-signature-field="name" value="${esc(s.name||r.responsible||'')}" autocomplete="off"></div><div class="field"><label for="signature-role">Cargo *</label><input id="signature-role" data-signature-field="role" value="${esc(s.role||'Responsable de la agencia')}" autocomplete="off"></div></div><p class="note" style="margin-top:18px">Firma con el dedo, un lápiz táctil o el mouse dentro del recuadro.</p><canvas id="signature-canvas" class="signature-canvas" aria-label="Área de firma del responsable de la agencia"></canvas><div class="toolbar" style="margin-top:12px"><button type="button" class="btn small" id="clear-signature">Borrar / Volver a firmar</button><span id="signature-pad-status" class="note">${s.image?(signatureMatches(r)?'Firma guardada en este dispositivo':'Los datos cambiaron: vuelve a firmar'):'Aún no se capturó una firma'}</span></div>`:omitted?`<div class="field" style="margin-top:16px"><label for="signature-reason">Motivo por el que no se obtuvo la firma *</label><textarea id="signature-reason" data-signature-field="reason" rows="3" placeholder="Por ejemplo: ausencia o negativa del responsable">${esc(s.reason||'')}</textarea></div>`:''}`}</section>`}
function signedSnapshotView(d){if(!d)return '<p class="note">No hay un resumen asociado.</p>';const lines=[['Agencia',d.agencyLabel?.name||agency(d.agency)?.name||d.agency],['Fecha / periodo',`${d.date} / ${d.period}`],['Stock Bs',money(d.stock)],['Faltante / sobrante Bs',`${money(d.short)} / ${money(d.over)}`],['Deuda por recaudación Bs',money(d.debt)],...(d.coi!==undefined?[['Diferencias COI Bs',money(d.coi)]]:[]),['Canastillos sistema / físicos',`${d.cratesSystem} / ${d.cratesPhysical}`],['Responsable registrado',d.responsible],['Firmante',`${d.signer?.name||''} · ${d.signer?.role||''}`]];return `<div class="signed-summary">${lines.map(([k,v])=>`<div class="reviewrow"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}<h3>Pendientes</h3>${Object.entries(d.pending||{}).filter(([,p])=>p.selected).map(([i,p])=>`<p>${esc(CATS[i]?.[0])}: Bs ${money(p.amount)}${p.detail?' · '+esc(p.detail):''}</p>`).join('')||'<p>Sin pendientes registrados.</p>'}<h3>Activos asignados</h3>${(d.assignedAssets||agency(d.agency)?.assets||[]).map(([code,desc])=>`<p>${esc(code)} · ${esc(desc)}: ${esc(d.assets?.[code]?.state||'Sin verificar')}${d.assets?.[code]?.note?' · '+esc(d.assets[code].note):''}</p>`).join('')}<h3>Activos adicionales</h3>${(d.extraAssets||[]).map(x=>`<p>${esc(x.noCode?'Sin código: '+x.codeReason:x.code)} · ${esc(x.description)} · ${esc(x.state)}${x.note?' · '+esc(x.note):''}</p>`).join('')||'<p>Sin activos adicionales.</p>'}<h3>Documentos</h3>${DOCS.map((n,i)=>`<p>${esc(n)}: Tiene ${esc(d.docs?.[i]?.has)} · Vigente ${esc(d.docs?.[i]?.valid)}</p>`).join('')}${d.notes?'<h3>Observaciones</h3><p>'+esc(d.notes)+'</p>':''}</div>`}
function validateAdditions(upTo=5){if(upTo<3)return null;const r=recordDefaults(current),a=agency(r.agency),seen=new Set();for(const x of r.extraAssets){const code=String(x.code||'').trim().toUpperCase();if(!x.description?.trim()||!['Buen estado','Mal estado'].includes(x.state))return[3,'Completa la descripción y el estado de cada activo adicional.'];if(x.noCode){if(!x.codeReason?.trim())return[3,'Indica por qué el activo adicional no tiene un código identificable.']}else{if(!code)return[3,'Registra el código de cada activo adicional o indica que no es legible.'];if(seen.has(code)||(a?.assets||[]).some(([c])=>c.trim().toUpperCase()===code))return[3,'El código '+code+' ya figura en este inventario. Verifica el listado antes de agregarlo.'];seen.add(code)}}if(upTo<5||editMode&&r.status==='final')return null;const s=r.signature;if(!['signed','omitted'].includes(s.mode))return[5,'Registra la firma del responsable o selecciona “No se obtuvo firma”.'];if(s.mode==='omitted'&&!s.reason?.trim())return[5,'Indica el motivo por el que no se obtuvo la firma.'];if(s.mode==='signed'){if(!s.name?.trim()||!s.role?.trim())return[5,'Completa el nombre y el cargo del responsable que firma.'];if(!s.image||!s.points?.some(p=>p.length>1))return[5,'Captura la firma dentro del recuadro.'];if(!signatureMatches(r))return[5,'Los datos cambiaron después de firmar. Revisa el resumen y solicita una nueva firma.']}return null}
function bindAdditions(){if(!current)return;recordDefaults(current);document.getElementById('add-extra-asset')?.addEventListener('click',()=>{if(!canEdit())return;current.extraAssets.push({id:makeId(),code:'',noCode:false,codeReason:'',description:'',state:'',note:'',review:'Pendiente de revisión'});saveIfDraft();render()});document.querySelectorAll('[data-remove-extra]').forEach(b=>b.onclick=()=>{if(!canEdit())return;current.extraAssets.splice(Number(b.dataset.removeExtra),1);saveIfDraft();render()});document.querySelectorAll('[data-extra-key]').forEach(el=>el.addEventListener(el.tagName==='SELECT'?'change':'input',()=>{if(!canEdit())return;const x=current.extraAssets[Number(el.dataset.extraIndex)],k=el.dataset.extraKey;if(k==='review'&&!admin())return;x[k]=el.value;saveIfDraft()}));document.querySelectorAll('[data-extra-nocode]').forEach(el=>el.onchange=()=>{if(!canEdit())return;const x=current.extraAssets[Number(el.dataset.extraNocode)];x.noCode=el.checked;if(x.noCode)x.code='';else x.codeReason='';saveIfDraft();render()});document.querySelector('[data-signature-mode]')?.addEventListener('change',e=>{if(!canEdit()||current.status==='final')return;const s=current.signature;s.mode=e.target.value==='Firmar'?'signed':e.target.value==='No se obtuvo firma'?'omitted':'';s.name=s.name||current.responsible;s.points=[];s.image='';s.snapshot=null;s.capturedAt='';s.reason='';saveIfDraft();render()});document.querySelectorAll('[data-signature-field]').forEach(el=>el.oninput=()=>{if(!canEdit()||current.status==='final')return;current.signature[el.dataset.signatureField]=el.value;saveIfDraft();const status=document.getElementById('signature-pad-status');if(status&&current.signature.image)status.textContent=signatureMatches(current)?'Firma guardada en este dispositivo':'Los datos cambiaron: vuelve a firmar'});document.getElementById('clear-signature')?.addEventListener('click',()=>{if(!canEdit()||current.status==='final')return;Object.assign(current.signature,{points:[],image:'',snapshot:null,capturedAt:''});saveIfDraft();render()});setupSignaturePad()}
function setupSignaturePad(){const canvas=document.getElementById('signature-canvas');if(!canvas||!canEdit()||current.status==='final')return;const r=current,s=r.signature,ctx=canvas.getContext('2d');let active=null,stroke=null;const redraw=()=>{const rect=canvas.getBoundingClientRect(),ratio=window.devicePixelRatio||1;canvas.width=Math.round(rect.width*ratio);canvas.height=Math.round(rect.height*ratio);ctx.setTransform(ratio,0,0,ratio,0,0);ctx.fillStyle='#ffffff';ctx.fillRect(0,0,rect.width,rect.height);ctx.strokeStyle='#333333';ctx.lineWidth=2.4;ctx.lineCap='round';ctx.lineJoin='round';for(const path of s.points||[]){if(!path.length)continue;ctx.beginPath();ctx.moveTo(path[0].x*rect.width,path[0].y*rect.height);for(const p of path.slice(1))ctx.lineTo(p.x*rect.width,p.y*rect.height);ctx.stroke()}};redraw();const point=e=>{const b=canvas.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-b.left)/b.width)),y:Math.max(0,Math.min(1,(e.clientY-b.top)/b.height))}};canvas.addEventListener('pointerdown',e=>{if(active!==null||e.button>0)return;e.preventDefault();active=e.pointerId;canvas.setPointerCapture(e.pointerId);if(s.image&&!signatureMatches(r)){s.points=[];s.image='';s.snapshot=null}s.points??=[];stroke=[point(e)];s.points.push(stroke);redraw()});canvas.addEventListener('pointermove',e=>{if(e.pointerId!==active||!stroke)return;e.preventDefault();stroke.push(point(e));redraw()});const finish=e=>{if(e.pointerId!==active)return;active=null;stroke=null;const length=(s.points||[]).reduce((n,path)=>n+path.slice(1).reduce((sum,p,i)=>sum+Math.hypot(p.x-path[i].x,p.y-path[i].y),0),0);if(length>.02){s.image=canvas.toDataURL('image/png');s.capturedAt=new Date().toISOString();s.snapshot=inventorySnapshot(r);s.version=1;saveIfDraft();const status=document.getElementById('signature-pad-status');if(status)status.textContent='Firma guardada en este dispositivo'}else{s.points=[];s.image='';s.snapshot=null;saveIfDraft();redraw()}};canvas.addEventListener('pointerup',finish);canvas.addEventListener('pointercancel',finish);if(typeof ResizeObserver!=='undefined'){const obs=new ResizeObserver(()=>{if(!canvas.isConnected){obs.disconnect();return}redraw()});obs.observe(canvas)}}

window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();promptInstall=e});
window.addEventListener('online',()=>{if(page!=='form')render();toast('Conexión disponible. Se intentará sincronizar los registros pendientes.');sincronizarPendientes()});window.addEventListener('offline',()=>{if(page!=='form')render();toast('Sin internet. Puedes continuar guardando en este dispositivo.')});
if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{offlineReady=true;const s=document.getElementById('offline-status');if(s)s.textContent='Preparados en este navegador'}).catch(()=>{offlineReady=false});
render();
setTimeout(sincronizarPendientes, 2500);
syncTimer=setInterval(sincronizarPendientes,WAREIQ_SYNC_INTERVAL_MS);
